const buildCtx = $("Build Embedding Batch Request").item.json;
const candidate = buildCtx.candidate_profile;
const jobs = buildCtx.jobs || [];
const method = buildCtx.method || "hybrid";
const resp = $input.item.json;

const SYNONYMS = { "js":"javascript","javascript":"js","postgres":"postgresql","postgresql":"postgres","node":"node.js","nodejs":"node.js","node.js":"node","py":"python","k8s":"kubernetes","golang":"go" };
function norm(s){ return (s||"").toLowerCase().trim(); }
function expand(s){ const n=norm(s); const syn=SYNONYMS[n]; return syn? [n,syn] : [n]; }
function skillSetMatch(required, have){
  const haveNorm = new Set();
  (have||[]).forEach(function(h){ expand(h).forEach(function(x){ haveNorm.add(x); }); });
  let matched=[]; let missing=[];
  (required||[]).forEach(function(r){
    const variants = expand(r);
    const isMatch = variants.some(function(v){ return haveNorm.has(v); });
    if (isMatch) matched.push(r); else missing.push(r);
  });
  return { matched: matched, missing: missing };
}
function keywordScore(job, candidate){
  const required = job.required_skills || [];
  const have = (candidate.technical_skills||[]).concat(candidate.programming_languages||[]).concat(candidate.frameworks||[]).concat(candidate.tools||[]);
  if (required.length === 0) return { score: 100, matched: [], missing: [] };
  const r = skillSetMatch(required, have);
  const score = (r.matched.length / required.length) * 100;
  return { score: score, matched: r.matched, missing: r.missing };
}
function cosine(a, b) {
  if (!Array.isArray(a) || !Array.isArray(b) || a.length === 0 || a.length !== b.length) return null;
  let dot = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) { dot += a[i]*b[i]; na += a[i]*a[i]; nb += b[i]*b[i]; }
  const denom = Math.sqrt(na) * Math.sqrt(nb);
  return denom === 0 ? 0 : Math.max(0, Math.min(1, dot / denom));
}
function tokenOverlapProxy(job, candidate){
  const candTokens = new Set();
  (candidate.keywords||[]).concat(candidate.technical_skills||[]).concat(candidate.job_titles||[]).forEach(function(k){ norm(k).split(/\s+/).forEach(function(t){ if(t) candTokens.add(t); }); });
  const jobText = ((job.description||"") + " " + (job.job_title||"") + " " + (job.required_skills||[]).join(" ")).toLowerCase();
  const jobTokens = jobText.split(/[^a-z0-9.+#]+/).filter(Boolean);
  if (jobTokens.length === 0 || candTokens.size === 0) return 0;
  let hits = 0;
  jobTokens.forEach(function(t){ if (candTokens.has(t)) hits++; });
  return Math.min(1, (hits / jobTokens.length) * 3);
}
function experienceMatch(job, candidate){
  const required = job.required_experience_years;
  const have = candidate.experience_years || 0;
  if (required === undefined || required === null) return { candidate_years: have, required_years: null, satisfied: true };
  return { candidate_years: have, required_years: required, satisfied: have >= required };
}
function titleScore(job, candidate){
  const jt = norm(job.job_title);
  const titles = (candidate.job_titles||[]).concat(candidate.preferred_roles||[]).map(norm);
  return titles.some(function(t){ return jt.indexOf(t) !== -1 || t.indexOf(jt) !== -1; }) ? 1 : 0;
}
function educationScore(job, candidate){
  if (!job.education_requirement) return 1;
  const req = norm(job.education_requirement);
  return (candidate.education||[]).some(function(e){ return norm(e.degree).indexOf(req)!==-1 || req.indexOf(norm(e.degree))!==-1; }) ? 1 : 0;
}
function preferredSkillScore(job, candidate){
  const pref = job.preferred_skills || [];
  if (pref.length === 0) return 1;
  const have = (candidate.technical_skills||[]).concat(candidate.programming_languages||[]).concat(candidate.frameworks||[]).concat(candidate.tools||[]);
  const r = skillSetMatch(pref, have);
  return r.matched.length / pref.length;
}
function locationScore(job, candidate){
  if (!job.location) return 1;
  const jobLoc = norm(job.location);
  if (/remote/.test(jobLoc)) return 1;
  if (!candidate.location) return 1;
  const candLoc = norm(candidate.location);
  return (jobLoc.indexOf(candLoc) !== -1 || candLoc.indexOf(jobLoc) !== -1) ? 1 : 0;
}

let embeddings = null;
let semanticMethodUsed = "token_overlap_fallback";
if (resp && Array.isArray(resp.embeddings) && resp.embeddings.length === jobs.length + 1) {
  embeddings = resp.embeddings.map(function(e){ return e.values; });
  semanticMethodUsed = "gemini-embedding-001_cosine";
}

const WEIGHTS = { skill: 0.35, semantic: 0.25, experience: 0.15, preferred: 0.10, education: 0.05, title: 0.05, location: 0.05 };

const ranked = jobs.map(function(job, idx){
  const kw = keywordScore(job, candidate);
  let sem;
  if (embeddings) {
    const c = cosine(embeddings[0], embeddings[idx + 1]);
    sem = c === null ? tokenOverlapProxy(job, candidate) : c;
  } else {
    sem = tokenOverlapProxy(job, candidate);
  }
  const exp = experienceMatch(job, candidate);
  const expScore = exp.required_years === null ? 100 : (exp.satisfied ? 100 : Math.max(0, (exp.candidate_years / exp.required_years) * 100));
  const pref = preferredSkillScore(job, candidate) * 100;
  const edu = educationScore(job, candidate) * 100;
  const title = titleScore(job, candidate) * 100;
  const loc = locationScore(job, candidate) * 100;
  const hybridScore = (kw.score * WEIGHTS.skill) + (sem*100 * WEIGHTS.semantic) + (expScore * WEIGHTS.experience) + (pref * WEIGHTS.preferred) + (edu * WEIGHTS.education) + (title * WEIGHTS.title) + (loc * WEIGHTS.location);
  let finalScore;
  if (method === "keyword") finalScore = kw.score;
  else if (method === "semantic") finalScore = sem * 100;
  else finalScore = hybridScore;
  finalScore = Math.round(finalScore * 10) / 10;
  let decision;
  if (finalScore >= 75) decision = "APPLY";
  else if (finalScore >= 50) decision = "REVIEW";
  else decision = "REJECT";
  const explanationParts = [];
  explanationParts.push(kw.matched.length + "/" + ((job.required_skills||[]).length) + " required skills matched");
  if (kw.missing.length) explanationParts.push("missing: " + kw.missing.join(", "));
  explanationParts.push("experience " + exp.candidate_years + "y vs required " + (exp.required_years===null?"unspecified":exp.required_years+"y") + (exp.satisfied?" (met)":" (not met)"));
  explanationParts.push("semantic method: " + semanticMethodUsed);
  explanationParts.push("method=" + method + ", score=" + finalScore);
  return {
    job_id: job.job_id,
    job_title: job.job_title,
    company: job.company,
    application_url: job.application_url,
    match_score: finalScore,
    score_breakdown: { keyword_score: Math.round(kw.score*10)/10, semantic_score: Math.round(sem*100*10)/10, semantic_method: semanticMethodUsed, experience_score: Math.round(expScore*10)/10, preferred_skill_score: Math.round(pref*10)/10, education_score: Math.round(edu*10)/10, title_score: Math.round(title*10)/10, location_score: Math.round(loc*10)/10, weights: WEIGHTS, hybrid_score: Math.round(hybridScore*10)/10 },
    matched_skills: kw.matched,
    missing_skills: kw.missing,
    experience_match: exp,
    semantic_similarity: Math.round(sem*100)/100,
    decision: decision,
    explanation: explanationParts.join("; "),
    method: method,
    ranked_at: new Date().toISOString()
  };
});
ranked.sort(function(a,b){
  if (b.match_score !== a.match_score) return b.match_score - a.match_score;
  if (a.experience_match.satisfied !== b.experience_match.satisfied) return a.experience_match.satisfied ? -1 : 1;
  return (a.job_id||"").localeCompare(b.job_id||"");
});
return ranked.map(function(job){ return { json: job }; });

const input = $input.item.json;
const candidate = input.candidate_profile;
const jobs = input.jobs || [];
const method = input.method || "hybrid";

function candidateText(c) {
  const parts = [];
  parts.push((c.job_titles || []).join(" "));
  parts.push((c.preferred_roles || []).join(" "));
  parts.push((c.technical_skills || []).join(" "));
  parts.push((c.programming_languages || []).join(" "));
  parts.push((c.frameworks || []).join(" "));
  parts.push((c.tools || []).join(" "));
  parts.push((c.keywords || []).join(" "));
  return parts.join(" ").trim() || "candidate profile";
}
function jobText(j) {
  const parts = [j.job_title || "", j.description || "", (j.required_skills || []).join(" "), (j.preferred_skills || []).join(" ")];
  return parts.join(" ").trim() || "job posting";
}

const requests = [];
requests.push({ model: "models/gemini-embedding-001", content: { parts: [{ text: candidateText(candidate) }] } });
jobs.forEach(function(j) { requests.push({ model: "models/gemini-embedding-001", content: { parts: [{ text: jobText(j) }] } }); });

return [{ json: { requests: requests, candidate_profile: candidate, jobs: jobs, method: method } }];
